<script lang="ts">
 import {onMount} from 'svelte';
 import type {Evidence} from './types';
 import {dateTime,evidenceCopy} from './helpers';
 import {translate,type Language} from './i18n';
 type ErrorData={records:Evidence[];total:number;truncated:boolean;unit:string;policy:string};
 let {language='en',request,onfollow}:{language?:Language;request:(query:string,currentView:boolean)=>Promise<ErrorData>;onfollow:(event:Evidence)=>void}=$props();
 const t=(key:string)=>translate(key,language);
 let data=$state<ErrorData|null>(null),search=$state(''),query=$state(''),currentView=$state(false),loading=$state(false),error=$state(''),copied=$state<number|null>(null),updated=$state('');
 let generation=0,alive=true;
 async function refresh(){const version=++generation;loading=true;try{const result=await request(query,currentView);if(!alive||version!==generation)return;data=result;error='';updated=new Date().toISOString()}catch(e){if(alive&&version===generation)error=e instanceof Error?e.message:t('Unable to load errors.')}finally{if(alive&&version===generation)loading=false}}
 async function copy(event:Evidence){try{await navigator.clipboard.writeText(evidenceCopy(event));copied=event.id}catch{error=t('Copy unavailable. Select the displayed sanitized text.')}}
 function switchView(next:boolean){currentView=next;void refresh()}
 onMount(()=>{alive=true;void refresh();const interval=setInterval(()=>void refresh(),5000);return()=>{alive=false;generation++;clearInterval(interval)}});
</script>
<section class="errors-workspace" aria-label={t('Errors & exceptions')}>
 <p class="inspector-note">{t('Discover errors from the application, including background work and events without a visit. You do not need to be the person using the app.')}</p>
 <div class="errors-controls"><div class="segmented"><button class:chosen={!currentView} aria-pressed={!currentView} onclick={()=>switchView(false)}>{t('Whole application')}</button><button class:chosen={currentView} aria-pressed={currentView} onclick={()=>switchView(true)}>{t('Current graph filters')}</button></div><button class="quiet-button" disabled={loading} onclick={()=>void refresh()}>{t('Refresh')}</button></div>
 <form class="error-search" onsubmit={e=>{e.preventDefault();query=search.trim();void refresh()}}><label>{t('Find an error')}<input type="search" bind:value={search} maxlength="160" placeholder={t('Message, exception, service or trace ID')}/></label><button>{t('Search')}</button></form>
 {#if currentView}<p class="inspector-note">{t('Shows error records inside the selected dates; a journey can include later follow-up.')}</p>{/if}<div class="errors-counts"><span>{data?.records.length??0} / {data?.total??0} {t('diagnostic records')}{loading?' · '+t('Loading…'):''}</span><span>{currentView?t('Selected graph context'):t('Retained detail · last 30 days')}{updated?' · '+dateTime(updated):''}</span></div>
 {#if error}<p class="error" role="alert">{error}</p>{/if}
 {#if data?.truncated}<p class="warning">{t('Results are partial. Narrow the search or graph filters to inspect more evidence.')}</p>{/if}
 {#each data?.records??[] as event (event.id)}
  <details class="error-record"><summary><span class="error-symbol" aria-hidden="true">!</span><span><strong>{event.attrs?.['exception.type']||(event.name==='unnamed'?(event.attrs?.['log.message']||event.attrs?.['exception.message']||t('Error record')).split('\n')[0].slice(0,100):event.name)}</strong>{#if event.attrs?.['exception.message']||event.attrs?.['log.message']}<small class="error-preview">{(event.attrs['exception.message']||event.attrs['log.message']).slice(0,160)}</small>{/if}<small>{event.service||t('Unknown service')} · {event.source} · {event.signal}</small></span><span class="error-record-time">{dateTime(event.time)}<small>{t(event.severity>=21?'Fatal':event.severity>=17?'Error':'Exception')}</small></span></summary>
   <div class="error-record-body">
    {#if !event.attrs?.['diagnostic.policy']}<p class="inspector-note">{t('Earlier records may lack details omitted by the previous privacy policy.')}</p>{/if}<p class="mono">{event.name} · {event.version||t('Unknown version')}</p>
    {#if event.attrs?.['exception.message']||event.attrs?.['log.message']}<h3>{t('Message')}</h3><pre class="diagnostic-message">{event.attrs['exception.message']||event.attrs['log.message']}</pre>{/if}
    {#if event.attrs?.['exception.stacktrace']}<h3>{t('Stack trace')}</h3><p class="inspector-note">{t('Sanitized stack as emitted. Source maps have not been applied.')}</p><pre class="diagnostic-stack">{event.attrs['exception.stacktrace']}</pre>{:else}<p class="inspector-note">{t('No stack trace was retained for this record.')}</p>{/if}
    {#if event.attrs?.['diagnostic.truncated']}<p class="warning">{t('Diagnostic text was shortened to the retention limits.')}</p>{/if}
    <dl class="diagnostic-metadata"><div><dt>{t('Occurrence time')}</dt><dd>{dateTime(event.time)}</dd></div><div><dt>{t('Receipt time')}</dt><dd>{dateTime(event.receipt)}</dd></div>{#if event.trace}<div><dt>Trace ID</dt><dd class="mono">{event.trace}</dd></div>{/if}{#if event.span}<div><dt>Span ID</dt><dd class="mono">{event.span}</dd></div>{/if}<div><dt>{t('Producer')}</dt><dd>{event.source}</dd></div><div><dt>{t('Definition')}</dt><dd>v{event.definition}</dd></div></dl>
    <p class="inspector-note">{t(event.scope?'Correlation context is available; it does not establish a person or a cause.':'No visit correlation was supplied. This error remains discoverable without inventing a journey.')}</p>
    <div class="button-row"><button class="secondary" onclick={()=>copy(event)}>{t(copied===event.id?'Copied':'Copy sanitized context')}</button>{#if event.scope}<button class="quiet-button" onclick={()=>onfollow(event)}>{t('Explore related context')}</button>{/if}</div>
    <details class="diagnostic-fields"><summary>{t('Retained diagnostic fields')}</summary><pre>{JSON.stringify(event.attrs,null,2)}</pre></details>
   </div>
  </details>
 {:else}{#if !loading&&!error}<div class="empty-state"><h3>{t('No matching errors')}</h3><p>{t('Try the whole application or a different search. No records is not proof that no errors occurred.')}</p></div>{/if}{/each}
 <p class="inspector-note diagnostic-policy">{t('Messages and stacks are bounded and scrubbed before storage. Scrubbing is imperfect; emit controlled diagnostic text. Detail expires after 30 days. Record counts are not distinct incidents or people.')}</p>
 {#if data?.policy}<details><summary>{t('Diagnostic retention policy')}</summary><p class="inspector-note">{data.policy}</p></details>{/if}
</section>
<style>
.errors-controls{display:flex;align-items:center;gap:12px;justify-content:space-between;flex-wrap:wrap}.errors-controls .segmented button{font-size:11px;padding:9px 14px}.error-search{display:flex;align-items:end;gap:12px;margin:20px 0}.error-search label{flex:1;min-width:0;font-size:11px}.error-search input{font-size:13px}.errors-counts{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;color:var(--muted);font-size:10px;margin:12px 0 16px}.error-record{border:1px solid var(--line);border-radius:6px;background:var(--surface);margin:0 0 10px}.error-record>summary{display:flex;align-items:center;gap:12px;list-style:none;padding:14px 16px}.error-record>summary::-webkit-details-marker{display:none}.error-symbol{font-size:14px;font-weight:700;color:#a3493d;border:1px solid #c99b91;border-radius:50%;width:22px;height:22px;display:inline-flex;justify-content:center;align-items:center;flex-shrink:0}.error-record>summary>span:nth-child(2){min-width:0;flex:1}.error-record strong{font-size:13px;overflow-wrap:anywhere}.error-record small{display:block;font-size:10px;color:var(--muted);font-weight:400;margin-top:5px}.error-record-time{margin-left:auto;font-size:10px;white-space:nowrap;font-weight:400}.error-record-time small{color:#a3493d}.error-record-body{padding:0 20px 20px 50px}.error-record-body h3{font-size:11px;margin:18px 0 8px}.error-record-body pre{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;background:#f3f4ec;border:1px solid var(--line);border-radius:5px;padding:13px;font:11px/1.8 ui-monospace,SFMono-Regular,monospace;max-height:420px;overflow:auto}.diagnostic-metadata{display:grid;grid-template-columns:1fr 1fr;gap:10px;font-size:11px;margin-top:18px}.diagnostic-metadata dt{font-size:9px;color:var(--muted)}.diagnostic-metadata dd{margin:4px 0;overflow-wrap:anywhere}.diagnostic-fields{margin-top:18px}.diagnostic-fields>summary{font-size:11px;color:var(--muted);font-weight:500}.diagnostic-policy{border-top:1px solid var(--line);padding-top:18px;margin-top:24px}@media(max-width:650px){.errors-controls .segmented button{font-size:10px;padding:8px 10px}.error-search{gap:12px;flex-wrap:wrap}.error-search label{flex-basis:100%}.error-search button{width:100%}.error-record>summary{align-items:flex-start;gap:9px;padding:12px}.error-record>summary{display:grid;grid-template-columns:22px minmax(0,1fr)}.error-record-time{grid-column:2;white-space:normal;min-width:0;max-width:none;margin:0}.error-record-time small{display:inline;margin-left:8px}.error-record strong{font-size:11px}.error-record small{font-size:9px}.error-record-body{padding:0 14px 17px}.diagnostic-metadata{grid-template-columns:1fr}.errors-counts{font-size:9px}.error-record-body pre{font-size:10px}}
</style>
